<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\UserNameVO;
use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Holder\UserNameAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserNameAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserNameAttributeHolderUnitTest extends TestCase
{
        /**
         * Asserts that the code attribute is not assigned by default
         * and that getName returns null on a freshly created holder.
         */
        public function testNameNotAssignedByDefault(): void
        {
            // Arrange
            $holder = new ImplWithUserNameAttributeHolderUnitTest();

            // Assert
            $this->assertFalse($holder->isNameAssigned());
            $this->assertNull($holder->getName());
        }
}
class ImplWithUserNameAttributeHolderUnitTest
{
  use UserNameAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedNameRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultName();
    }}
